241	/**
242	 * The text of a definition must agree, operand by operand and side by side, with the formula the view
243	 * executes; a contradiction is a block, not a warning. The release view is debt less cash and investments;
244	 * the contractual view adds derivative liabilities and deducts derivative assets as well.
245	 */
246	function definitionDisagreement(name: "release" | "contractual", text: string): string | null {
247	  const parsed = parseDefinition(text);
248	  if (parsed.deducted === null) return `the ${name} definition never deducts anything; the view deducts cash and investments`;
249	  if (!DEBT.test(parsed.added)) return `the ${name} definition adds no debt line; the view sums loans, financings and debentures`;
250	  if (!DEBT_BASE_OK.test(parsed.added)) return `the ${name} definition does not add the whole debt base (loans, financings and debentures, or gross debt); the view sums all three`;
251	  if (FOREIGN.test(parsed.added) || FOREIGN.test(parsed.deducted)) return `the ${name} definition names a component that is not debt nor cash (${(FOREIGN.exec(parsed.added) ?? FOREIGN.exec(parsed.deducted))![0]}); the view has no such operand`;
252	  const deductedDebt = /emprestim|financiament|debenture|subordinad|divida bruta|gross debt|loan|borrowing/.exec(parsed.deducted.replace(/divida liquida|net debt/g, ""));
253	  if (deductedDebt) return `the ${name} definition deducts a debt operand (${deductedDebt[0]}); the view deducts only cash, investments and derivative assets`;
254	  if (!CASH.test(parsed.deducted)) return `the ${name} definition does not deduct cash; the view deducts cash and equivalents`;
255	  if (!INVESTMENTS.test(parsed.deducted)) return `the ${name} definition does not deduct financial investments; the view deducts them`;
256	  if (CASH.test(parsed.added) || INVESTMENTS.test(parsed.added)) return `the ${name} definition adds cash or investments; the view deducts them`;
257	  if (name === "release") {
258	    if (DERIVATIVES.test(plainText(text))) return "the release definition mentions derivatives; the release view executed excludes them";
259	    return foreignCheck(name, text);
260	  }
261	  if (!DERIVATIVE_LIABILITIES.test(parsed.added)) return "the contractual definition does not add derivative liabilities; the contractual view executed adds them";
262	  if (!DERIVATIVE_ASSETS.test(parsed.deducted)) return "the contractual definition does not deduct derivative assets; the contractual view executed deducts them";
263	  if (DERIVATIVE_ASSETS.test(parsed.added)) return "the contractual definition adds derivative assets; the view deducts them";
264	  if (DERIVATIVE_LIABILITIES.test(parsed.deducted)) return "the contractual definition deducts derivative liabilities; the view adds them";
265	  return foreignCheck(name, text);
266	}
