273	function canonical(input: z.infer<typeof debtLedgerInputSchema>) {
274	  return {
275	    ...input,
276	    rows: [...input.rows].sort((a, b) => compare(a.id, b.id)).map((row) => (row.obligation ? {...row, obligation: {...row.obligation, views: [...row.obligation.views].sort(compare)}} : row)),
277	    schedule: input.schedule ? {...input.schedule, periods: [...input.schedule.periods].sort((a, b) => compare(a.period, b.period))} : undefined,
278	  };
