284	export function buildDebtLedger(raw: DebtLedgerInput): DebtLedgerOutput {
285	  const input = canonical(debtLedgerInputSchema.parse(raw));
286	  const calculations: DebtLedgerOutput["trace"]["calculations"] = [];
287	  const record = (calculation: Omit<DebtLedgerOutput["trace"]["calculations"][number], "unit">) => calculations.push({...calculation, unit: input.unit});
288	  const rows = input.source === "release_only" ? [] : input.rows;
289	  const blockReasons: string[] = [];
290	  const incompleteReasons: string[] = [];
291	  const tolerance = d(input.tolerance.value);
292	  const toleranceOut = {value: input.tolerance.value, policyKey: input.tolerance.policyKey ?? null, policyVersion: input.tolerance.policyVersion ?? null};
293	
294	  const balances = Object.fromEntries(rows.map((row) => [row.id, row.balance]));
295	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
296	  // What the statements report as debt: the release view plus the contra lines; a row only an indenture includes stays out of the identity with the balance sheet.
297	  const reportedRows = rows.filter((row) => row.contra || row.obligation!.views.includes("release"));
298	  const contractualOnly = rows.filter((row) => !row.contra && !row.obligation!.views.includes("release"));
299	  const grossReported = reportedRows.reduce((sum, row) => sum.plus(row.balance), d(0));
300	  const grossBeforeContra = rows.filter((row) => !row.contra).reduce((sum, row) => sum.plus(row.balance), d(0));
301	  const priorKnown = rows.length > 0 && rows.every((row) => row.priorBalance !== null);
302	  const grossPrior = priorKnown ? rows.reduce((sum, row) => sum.plus(row.priorBalance!), d(0)) : null;
303	  record({id: "financial.debt_ledger_balance", formula: "sum(rows.balance)", operands: balances, result: out(gross)});
304	  record({id: "financial.debt_ledger_balance_reported", formula: "sum(rows.balance where row in release view or contra)", operands: Object.fromEntries(reportedRows.map((row) => [row.id, row.balance])), result: out(grossReported)});
305	  record({id: "financial.debt_ledger_balance_before_contra", formula: "sum(rows.balance where not contra)", operands: Object.fromEntries(rows.filter((row) => !row.contra).map((row) => [row.id, row.balance])), result: out(grossBeforeContra)});
306	  if (grossPrior) record({id: "financial.debt_ledger_balance_prior", formula: "sum(rows.priorBalance)", operands: Object.fromEntries(rows.map((row) => [row.id, row.priorBalance!])), result: out(grossPrior)});
307	
308	  if (input.source === "release_only") blockReasons.push("only a release is in the base; a ledger needs the debt note of the financial statements, so no row is produced");
309	  if (input.source === "note" && rows.length === 0 && !input.noDebtEvidence) blockReasons.push("no rows and no evidence that the company has no onerous debt: silence is not an empty ledger");
310	  if (input.source === "note" && rows.length === 0 && input.noDebtEvidence && !input.balanceSheet) blockReasons.push("the base claims no onerous debt but no balance sheet proves a zero balance; an empty ledger needs the balance sheet");
311	  if (input.noDebtEvidence && rows.length > 0) blockReasons.push("the base claims no onerous debt and the note carries rows; the contradiction blocks the ledger");
312	  if (rows.length === 0 && input.noDebtEvidence && input.balanceSheet && !d(input.balanceSheet.current).plus(input.balanceSheet.nonCurrent).isZero()) {
313	    blockReasons.push("the base claims no onerous debt but the balance sheet carries debt totals; the contradiction blocks the ledger");
314	  }
